"use strict";
import { Lock, Check, Clock, AlertTriangle } from "react-feather";
import styled from "styled-components";
import { Flex, Separator, SpinningLoader, Text, styled as UiStyled, useSporeColors } from "ui/src";
import { colors as BaseColor } from "ui/src/theme";
import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
const InfoContainer = styled(Flex)`
  background-color: ${({ $colors }) => $colors.surface2.val};
  border: 1px solid ${({ $colors, $type }) => $type === "warning" ? $colors.statusCritical.val : $type === "success" ? $colors.statusSuccess.val : $colors.neutral3.val};
  border-radius: 12px;
  padding: 16px;
`;
const ItemWrapper = UiStyled(Flex, {
  row: true,
  gap: "$gap8",
  alignItems: "center"
});
const IconWrapper = UiStyled(Flex, {
  width: 28,
  height: 28,
  borderRadius: "$roundedFull",
  backgroundColor: "$surface3",
  centered: true
});
const StepText = UiStyled(Text, {
  variants: {
    status: {
      complete: {
        color: "$accent1"
      },
      pending: {
        color: "$neutral2"
      },
      blocked: {
        color: "$statusCritical"
      }
    }
  }
});
const DepositButton = styled.button`
  all: unset;
  padding: 16px 10px;
  background-color: ${({ theme, disabled }) => disabled ? theme.surface3 : theme.accent1};
  color: ${({ theme, disabled }) => disabled ? theme.neutral3 : theme.surface1};
  border-radius: 12px;
  cursor: ${({ disabled }) => disabled ? "not-allowed" : "pointer"};
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all 0.2s ease;
  opacity: ${({ disabled }) => disabled ? 0.6 : 1};
  &:hover {
    opacity: ${({ disabled }) => disabled ? 0.6 : 0.8};
  }
`;
export default function RelayDepositReviewer({
  selectedLock,
  selectedRelay,
  hasSelectedLockVoted,
  hasLingeringVotes,
  depositDisabledReason,
  onDeposit,
  isDepositing,
  transactionState
}) {
  const colors = useSporeColors();
  const navigate = useNavigate();
  const steps = [
    {
      icon: Lock,
      text: selectedLock ? `Selected lock #${selectedLock.id}` : "Select the lock you want to deposit",
      status: selectedLock ? "complete" : "pending"
    },
    {
      icon: Check,
      text: selectedRelay ? `Selected ${selectedRelay.relayName ?? `ABX Vault #${selectedRelay.id}`}` : "Choose an ABX Vault strategy",
      status: selectedRelay ? "complete" : "pending"
    },
    {
      icon: Check,
      text: "Review unlock date extension to maximum duration",
      status: selectedLock ? "complete" : "pending"
    }
  ];
  if (hasSelectedLockVoted) {
    steps.push({
      icon: AlertTriangle,
      text: "Wait until next epoch (voted this epoch - reset not available)",
      status: "blocked"
    });
  } else if (hasLingeringVotes) {
    steps.push({
      icon: AlertTriangle,
      text: "Reset your votes before depositing (has unreset votes)",
      status: "blocked"
    });
  }
  steps.push({
    icon: Clock,
    text: transactionState.isConfirming || isDepositing ? "Transaction pending on-chain..." : "Confirm deposit transaction",
    status: transactionState.isSuccess && !isDepositing ? "complete" : "pending"
  });
  useEffect(() => {
    if (transactionState.isSuccess && !isDepositing) {
      navigate("/locks");
    }
  }, [transactionState.isSuccess, isDepositing]);
  const buttonDisabled = isDepositing || transactionState.isConfirming || !selectedLock || !selectedRelay || hasSelectedLockVoted || hasLingeringVotes || Boolean(depositDisabledReason);
  const handleDepositClick = () => {
    if (!buttonDisabled) {
      onDeposit().catch(() => void 0);
    }
  };
  return <Flex
    flexDirection="column"
    p={"$spacing16"}
    borderRadius={"$rounded12"}
    gap={"$gap24"}
    borderWidth={1}
    borderColor={"$surface3"}
    style={{
      background: `linear-gradient(180deg, ${colors.surface2.variable} 0%, transparent 100%)`
    }}
  >
      <Text variant="buttonLabel1">ABX Vault Deposit</Text>

      <Flex flexDirection="column">
        {steps.map((item, index) => <Flex key={`${item.text}-${index}`}>
            {index > 0 && <Separator left={14} vertical minHeight={22} width={2} borderColor={"$surface3"} />}

            <ItemWrapper>
              <IconWrapper>
                <Flex>
                  <item.icon
    size={14}
    color={item.status === "complete" ? BaseColor.greenVibrant : item.status === "blocked" ? BaseColor.redVibrant : BaseColor.brownVibrant}
  />
                </Flex>
              </IconWrapper>

              <StepText variant="body3" status={item.status}>
                {item.text}
              </StepText>
            </ItemWrapper>
          </Flex>)}
      </Flex>

      {hasSelectedLockVoted && selectedLock && <InfoContainer $colors={colors} $type="warning">
          <Flex row gap="$gap8" alignItems="flex-start">
            <AlertTriangle size={16} color={colors.statusCritical.val} />
            <Flex flexDirection="column" gap="$gap4" flex={1}>
              <Text variant="buttonLabel3" color={colors.statusCritical.val}>
                Cannot Deposit This Epoch
              </Text>
              <Text variant="body3" color={colors.neutral2.val}>
                This lock has already voted in the current epoch. Vote resets are not allowed in the same epoch you voted. You must wait until the next epoch begins before depositing into an ABX Vault.
              </Text>
            </Flex>
          </Flex>
        </InfoContainer>}

      {!hasSelectedLockVoted && hasLingeringVotes && selectedLock && <InfoContainer $colors={colors} $type="info">
          <Flex row gap="$gap8" alignItems="flex-start">
            <AlertTriangle size={16} color={colors.neutral2.val} />
            <Flex flexDirection="column" gap="$gap8" flex={1}>
              <Flex flexDirection="column" gap="$gap4">
                <Text variant="buttonLabel3" color={colors.neutral1.val}>
                  Reset Votes Required
                </Text>
                <Text variant="body3" color={colors.neutral2.val}>
                  This lock has unreset votes from a previous epoch. You must reset your votes before depositing into an ABX Vault.
                </Text>
              </Flex>
              <Text
    py="$spacing8"
    px="$spacing12"
    variant="buttonLabel3"
    borderRadius="$roundedFull"
    backgroundColor="$accent1"
    cursor="pointer"
    transition="all 0.2s ease-in-out"
    color="$surface1"
    hoverStyle={{ opacity: 0.8 }}
    alignSelf="flex-start"
    onPress={() => navigate(`/locks/modify-lock?lockId=${selectedLock.id}&tab=Reset`)}
  >
                Reset Votes for Lock #{selectedLock.id}
              </Text>
            </Flex>
          </Flex>
        </InfoContainer>}

      {depositDisabledReason && !hasSelectedLockVoted && !hasLingeringVotes && <Text variant="body4" color="$statusWarning">
          {depositDisabledReason}
        </Text>}

      <DepositButton onClick={handleDepositClick} disabled={buttonDisabled}>
        <Flex row alignItems="center" gap="$gap8">
          {(isDepositing || transactionState.isConfirming || transactionState.isLoading) && <SpinningLoader size={16} />}
          <Text variant="buttonLabel2" color="inherit">
            {isDepositing || transactionState.isConfirming ? "Depositing\u2026" : "Deposit to Vault"}
          </Text>
        </Flex>
      </DepositButton>
    </Flex>;
}
